def __getitem__(self, item):
    if isinstance(item, int):
        return self.fixed[item]
    elif isinstance(item, slice):
        # Support slice access - return a new Result with sliced data
        sliced_fixed = self.fixed[item]
        sliced_named = {k: v for k, v in self.named.items()}
        # Slicing named dict isn't standard; just pass through the dict as-is
        # since dicts don't support slicing. The user can slice fixed results.
        return Result(sliced_fixed, sliced_named, self.spans)
    return self.named[item]

def __contains__(self, item):
    '''Check if a value exists in the result (in fixed or named values).'''
    if item in self.fixed:
        return True
    if item in self.named.values():
        return True
    return False

